/// Whether reading `property` from `object` is a known side-effect-free access on a
/// built-in global object.
///
/// This handles two-level accesses such as `Math.PI` or `console.log`, and the specific
/// three-level `Object.prototype.<method>` accesses. `object` is required to be a global
/// reference so that user-defined values shadowing these names are not treated as pure.
fn is_pure_global_property_read<'a>(
    object: &Expression<'a>,
    property: &str,
    ctx: &impl MayHaveSideEffectsContext<'a>,
) -> bool {
    // Three-level chain: `Object.prototype.<method>`.
    // Only `Object.prototype` is allowed here; chains such as `Math.PI.toString` or
    // `Array.prototype.push` are not treated as side-effect free.
    if let Expression::StaticMemberExpression(member) = object {
        if let Expression::Identifier(obj_ident) = &member.object
            && obj_ident.name == "Object"
            && member.property.name == "prototype"
            && ctx.is_global_reference(obj_ident)
        {
            return matches!(
                property,
                "hasOwnProperty"
                    | "isPrototypeOf"
                    | "toString"
                    | "valueOf"
                    | "propertyIsEnumerable"
            );
        }
        return false;
    }

    // Two-level access: `<Global>.<property>`.
    let Expression::Identifier(obj_ident) = object else {
        return false;
    };
    if !ctx.is_global_reference(obj_ident) {
        return false;
    }
    match obj_ident.name.as_str() {
        "Math" => matches!(property, "PI" | "E" | "abs" | "floor" | "random"),
        "Object" => matches!(property, "keys" | "create" | "assign" | "prototype"),
        "Reflect" => matches!(property, "apply" | "get"),
        "Symbol" => matches!(property, "iterator" | "asyncIterator"),
        "JSON" => matches!(property, "parse" | "stringify"),
        "console" => matches!(property, "log" | "error" | "warn"),
