557	/// Whether reading `property` from `object` is a known side-effect-free access on a
558	/// built-in global object.
559	///
560	/// This handles two-level accesses such as `Math.PI` or `console.log`, and the specific
561	/// three-level `Object.prototype.<method>` accesses. `object` is required to be a global
562	/// reference so that user-defined values shadowing these names are not treated as pure.
563	fn is_pure_global_property_read<'a>(
564	    object: &Expression<'a>,
565	    property: &str,
566	    ctx: &impl MayHaveSideEffectsContext<'a>,
567	) -> bool {
568	    // Three-level chain: `Object.prototype.<method>`.
569	    // Only `Object.prototype` is allowed here; chains such as `Math.PI.toString` or
570	    // `Array.prototype.push` are not treated as side-effect free.
571	    if let Expression::StaticMemberExpression(member) = object {
572	        if let Expression::Identifier(obj_ident) = &member.object
573	            && obj_ident.name == "Object"
574	            && member.property.name == "prototype"
575	            && ctx.is_global_reference(obj_ident)
