577	            return matches!(
578	                property,
579	                "hasOwnProperty"
580	                    | "isPrototypeOf"
581	                    | "toString"
582	                    | "valueOf"
583	                    | "propertyIsEnumerable"
584	            );
585	        }
586	        return false;
587	    }
588	
589	    // Two-level access: `<Global>.<property>`.
590	    let Expression::Identifier(obj_ident) = object else {
591	        return false;
592	    };
593	    if !ctx.is_global_reference(obj_ident) {
594	        return false;
595	    }
596	    match obj_ident.name.as_str() {
597	        "Math" => matches!(property, "PI" | "E" | "abs" | "floor" | "random"),
598	        "Object" => matches!(property, "keys" | "create" | "assign" | "prototype"),
599	        "Reflect" => matches!(property, "apply" | "get"),
600	        "Symbol" => matches!(property, "iterator" | "asyncIterator"),
601	        "JSON" => matches!(property, "parse" | "stringify"),
602	        "console" => matches!(property, "log" | "error" | "warn"),
603	        _ => false,
604	    }
