//! Scratch harness for manual testing (temporary).

use oxc_allocator::Allocator;
use oxc_codegen::{Codegen, CodegenOptions};
use oxc_minifier::{
    CompressOptions, CompressOptionsKeepNames, CompressOptionsUnused, Compressor,
};
use oxc_parser::{ParseOptions, Parser};
use oxc_span::SourceType;

fn default_options() -> CompressOptions {
    CompressOptions {
        drop_debugger: false,
        unused: CompressOptionsUnused::Keep,
        ..CompressOptions::smallest()
    }
}

fn run(source_text: &str, options: CompressOptions) -> String {
    let allocator = Allocator::default();
    let source_type = SourceType::mjs();
    let ret = Parser::new(&allocator, source_text, source_type)
        .with_options(ParseOptions { allow_return_outside_function: true, ..Default::default() })
        .parse();
    assert!(!ret.panicked, "{source_text}");
    let mut program = ret.program;
    Compressor::new(&allocator).build(&mut program, options);
    Codegen::new()
        .with_options(CodegenOptions { single_quote: true, ..Default::default() })
        .build(&program)
        .code
}

fn main() {
    let cases = [
        // Symbol() inlining
        "function f() { let x = Symbol(); return x }",
        "let x = Symbol(); foo(x)",
        // arguments copy loop
        "function _() { for (var r = [], a = 0; a < arguments.length; a++) r[a] = arguments[a]; console.log(r) }",
        "function _() { for (var e = arguments.length, r = Array(e > 1 ? e - 1 : 0), a = 1; a < e; a++) r[a - 1] = arguments[a]; console.log(r) }",
        // if-else same fn diff arg to OR
        "function f(cond, other) { if (cond) g(cond); else g(other); }",
        "function f(a) { if (a.b) g(a.b); else g(x); }",
        "function f(cond, other) { let g = h; if (cond) g(cond); else g(other); }",
        "let a = foo(), b = bar(); a ? b(a) : b(c)",
        "function f(cond, other) { cond ? g(cond) : g(other); }",
        "function f(cond, other) { if (cond) Math.floor(cond); else Math.floor(other); }",
        "function f(cond, other) { if (cond) console.log(cond); else console.log(other); }",
        "function f(cond, other) { cond ? Math.floor(cond) : Math.floor(other); }",
    ];
    for c in &cases {
        println!("IN : {c}");
        println!("OUT: {}\n", run(c, default_options()));
    }

    let keep = CompressOptions { keep_names: CompressOptionsKeepNames::all_true(), ..default_options() };
    let keep_cases = [
        "var x = function() {}; var y = x; console.log(y.name)",
        "var x = function foo() {}; var y = x; console.log(y.name)",
        "var x = class {}; var y = x; console.log(y.name)",
        "var x = class Foo {}; var y = x; console.log(y.name)",
    ];
    for c in &keep_cases {
        println!("KIN : {c}");
        println!("KOUT: {}\n", run(c, keep.clone()));
    }
}
