+#[rustfmt::skip]
+fn is_pure_constructor(name: &str) -> bool {
+    matches!(name, "Set" | "Map" | "WeakSet" | "WeakMap" | "ArrayBuffer" | "Date"
+            | "Boolean" | "Error" | "EvalError" | "RangeError" | "ReferenceError"
+            | "SyntaxError" | "TypeError" | "URIError" | "Number" | "Object" | "String")
+}
